import { database } from "@repo/database";

/** 이보다 오래된 미완료 회차는 죽은 작업으로 보고 편집을 막지 않는다(영구 잠금 방지). */
const IN_FLIGHT_WINDOW_MS = 30 * 60 * 1000;

/** 측정 결과 저장(Tracking) 마무리 단계가 아직 끝나지 않았음을 뜻하는 표식 값들. */
const UNFINISHED_TRACKING_STAGES = [
  "pending",
  "reconciling",
  "failed",
  "unknown",
] as const;

/**
 * 이 브랜드의 측정이 **지금 진행 중이거나 결과 저장이 덜 끝났는가**(2026-10-13).
 *
 * 🔴 왜: 측정 결과 저장(`persistAuditTracking`)은 질문을 **텍스트로 upsert** 한다.
 *   측정 도중(또는 저장 마무리 전)에 고객이 질문을 지우거나 고치면, 저장 단계가 지운 질문을
 *   **`isAutoGenerated: true`(고객 질문)로 다시 만들어** 되살린다(삭제한 질문이 살아나고 플랜 할당량을 먹는다).
 *   저장 경로(행 키·매니페스트로 잠긴 멱등 쓰기)를 건드리지 않고, 편집 쪽에서 그 시간대를 막는다.
 *
 * 진행 중 = 최근 30분 안의 queued/processing 회차, 또는 완료됐지만 Tracking 저장 단계가 미완인 회차.
 */
export async function hasInFlightMeasurement(
  brandId: string,
  now: Date = new Date()
): Promise<boolean> {
  const job = await database.auditJob.findFirst({
    where: {
      brandId,
      createdAt: { gte: new Date(now.getTime() - IN_FLIGHT_WINDOW_MS) },
      OR: [
        { status: { in: ["queued", "processing"] } },
        {
          status: "completed",
          OR: UNFINISHED_TRACKING_STAGES.map((stage) => ({
            postprocessing: { path: ["tracking"], equals: stage },
          })),
        },
      ],
    },
    select: { id: true },
  });
  return job !== null;
}
